{
  "name": "Cytomat 自动化孵育存储柜",
  "name_en": "Cytomat Incubation Plate Hotel",
  "manufacturer": "Thermo Fisher Scientific",
  "description": "一种用于微孔板（MTP）自动化存储与孵育的立式设备。包含可开关的舱门、内部货架/存储位、传输站（transfer station）和可伸缩的取放装置（铲/移载机构），并配有条码读取、摇床（振荡器）以及温度、CO₂、湿度和 O₂ 等环境传感与控制能力，常用于自动化实验室中板材的存取、临时暴露以及长期孵育保存。",
  "description_en": "A vertical automated plate hotel/incubator for microplates (MTP). The unit provides door-controlled compartments, stacked storage racks, a transfer station for external robots, and an internal shuttle/shovel mechanism to move plates between storage, wait and exposed positions. It typically includes barcode reading, shaker modules, and environmental sensors/controls for temperature, CO2, humidity and O2 for automated storage and incubation workflows.",
  "actions": [
    {
      "action_name": "auto-action_exposed_to_storage",
      "description": "将设备外部暴露位的微孔板移回指定储存位，放置后移动到等待位并关闭门。",
      "description_en": "Move an MTP from the exposed (external) position back into a specified storage location, then move to the wait position and close the door."
    },
    {
      "action_name": "auto-action_exposed_to_wait",
      "description": "将暴露位的微孔板移回设备内部的等待位并关闭门。",
      "description_en": "Return an MTP from the exposed position to the internal wait position and close the door."
    },
    {
      "action_name": "auto-action_read_barcode",
      "description": "读取指定存储位置（或两个位置）的条形码信息。",
      "description_en": "Read the barcode(s) of specified storage location(s)."
    },
    {
      "action_name": "auto-action_storage_to_exposed",
      "description": "从储存位取出微孔板并将其运输到设备外部的暴露位供取用。",
      "description_en": "Retrieve an MTP from storage and transport it to the exposed position outside the device."
    },
    {
      "action_name": "auto-action_storage_to_transfer",
      "description": "从储存位取出微孔板，打开门并放置到传输站（transfer station），随后关闭门。",
      "description_en": "Retrieve an MTP from storage, open the door and place it onto the transfer station, then close the door."
    },
    {
      "action_name": "auto-action_storage_to_wait",
      "description": "从储存位取出微孔板并移动到内部的等待位。",
      "description_en": "Retrieve an MTP from storage and move it to the internal wait position."
    },
    {
      "action_name": "auto-action_transfer_to_storage",
      "description": "从传输站取回载板，打开门并将其放入指定储存位，然后关门。",
      "description_en": "Open the lift/door, pick up a plate from the transfer station and place it into a specified storage location, then close the door."
    },
    {
      "action_name": "auto-action_transfer_to_wait",
      "description": "从传输站取回微孔板并将其带回到内部等待位，随后关闭门。",
      "description_en": "Retrieve an MTP from the transfer station, return it to the internal wait position, and close the door."
    },
    {
      "action_name": "auto-action_wait_to_exposed",
      "description": "将等待位的微孔板移动到设备外部的暴露位以便外部取用。",
      "description_en": "Move an MTP from the internal wait position to the exposed (external) position for external access."
    },
    {
      "action_name": "auto-action_wait_to_storage",
      "description": "把等待位的微孔板放入指定的储存位，然后返回等待位。",
      "description_en": "Move an MTP from the wait position into a specified storage location, then return to the wait position."
    },
    {
      "action_name": "auto-action_wait_to_transfer",
      "description": "打开门并将等待位的微孔板放到传输站，然后返回等待位并关闭门。",
      "description_en": "Open the door, place the plate from the wait position onto the transfer station, return to wait position, and close the door."
    },
    {
      "action_name": "auto-close_door",
      "description": "关闭孵育柜或货舱的门。",
      "description_en": "Close the incubator/storage door."
    },
    {
      "action_name": "auto-fetch_plate_to_loading_tray",
      "description": "将指定的微孔板移动到装载托盘或外部上料托盘位置以供取放。",
      "description_en": "Move a specified plate to the loading tray or external loading position for pickup."
    },
    {
      "action_name": "auto-init_shakers",
      "description": "初始化设备内的振荡/摇床模块以准备工作。",
      "description_en": "Initialize the internal shaker modules to prepare them for operation."
    },
    {
      "action_name": "auto-initialize",
      "description": "对设备执行初始化准备（例如复位、回原点并准备接收命令）。",
      "description_en": "Initialize and prepare the Cytomat for operation (e.g., reset, home axes, clear preconditions)."
    },
    {
      "action_name": "auto-open_door",
      "description": "打开孵育柜或货舱的门以便交互或放取微孔板。",
      "description_en": "Open the incubator/storage door to allow interaction or plate transfer."
    },
    {
      "action_name": "auto-reset_error_register",
      "description": "清除或重置设备的错误寄存器/错误状态。",
      "description_en": "Reset or clear the device error register / error state."
    },
    {
      "action_name": "auto-send_action",
      "description": "发送动作命令并在超时时间内等待完成，返回概览寄存器状态。",
      "description_en": "Send an action command, wait (with timeout) for completion, and return the overview register state."
    },
    {
      "action_name": "auto-send_command",
      "description": "发送低级命令到设备并处理重试与响应（包含错误与忙碌重试机制）。",
      "description_en": "Send a low-level command to the device and handle retries and responses (including busy/recognition retries)."
    },
    {
      "action_name": "auto-serialize",
      "description": "导出或序列化设备当前配置/状态以便传输或记录。",
      "description_en": "Serialize or export the device's current configuration/state for transmission or recording."
    },
    {
      "action_name": "auto-set_racks",
      "description": "设置或定义设备内部的货架/储存位布局与配置。",
      "description_en": "Set or define the internal rack/storage location layout and configuration."
    },
    {
      "action_name": "auto-set_shaking_frequency",
      "description": "为一个或多个振荡模块设置振荡频率。",
      "description_en": "Set the shaking frequency for one or more shaker modules."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置 孵育温度",
      "description_en": "set incubation temperature"
    },
    {
      "action_name": "auto-setup",
      "description": "执行设备启动准备（配置运行所需的初始状态和参数）。",
      "description_en": "Perform device setup to prepare initial state and parameters for operation."
    },
    {
      "action_name": "auto-shovel_in",
      "description": "将内部铲/取放臂伸入设备以进行抓取或放置操作（进仓动作）。",
      "description_en": "Move the internal shovel/shuttle into the device to pick or place plates (ingress action)."
    },
    {
      "action_name": "auto-shovel_out",
      "description": "将内部铲/取放臂移出到可访问位置以便外部取放（出仓动作）。",
      "description_en": "Move the internal shovel/shuttle out to an accessible position for external pickup or placement (egress action)."
    },
    {
      "action_name": "auto-start_shaking",
      "description": "启动振荡/摇床（按指定频率和可选的振荡模块）。",
      "description_en": "Start shaking on the shaker(s) at a specified frequency (optionally for selected shaker units)."
    },
    {
      "action_name": "auto-stop",
      "description": "停止当前运行的任务或中断正在进行的动作（安全停止）。",
      "description_en": "Stop the current running task or abort an ongoing action (safe stop)."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止一个或多个振荡模块的振荡动作。",
      "description_en": "Stop shaking on one or more shaker modules."
    },
    {
      "action_name": "auto-take_in_plate",
      "description": "接收来自外部的微孔板并将其放置到指定的设备内部位置（入库）。",
      "description_en": "Accept a plate from an external source and place it into a specified internal location (take-in)."
    },
    {
      "action_name": "auto-wait_for_task_completion",
      "description": "等待设备当前任务完成（监控概览寄存器直到非忙碌或超时）。",
      "description_en": "Wait for the device's current task to complete (monitor the overview register until not busy or timeout)."
    },
    {
      "action_name": "auto-wait_for_transfer_station",
      "description": "等待传输站达到期望状态：占用或空闲。",
      "description_en": "Wait until the transfer station reaches the desired state: occupied or unoccupied."
    },
    {
      "action_name": "auto-get_overview_register",
      "description": "获取 概览寄存器（设备总体状态）",
      "description_en": "get overview register (summary of device status)"
    },
    {
      "action_name": "auto-get_warning_register",
      "description": "获取 警告寄存器（当前警告信息）",
      "description_en": "get warning register (current warnings)"
    },
    {
      "action_name": "auto-get_error_register",
      "description": "获取 错误寄存器（当前错误或故障代码）",
      "description_en": "get error register (current errors/fault codes)"
    },
    {
      "action_name": "auto-get_action_register",
      "description": "获取 操作寄存器（当前或最近动作的状态）",
      "description_en": "get action register (status of current or recent actions)"
    },
    {
      "action_name": "auto-get_swap_register",
      "description": "获取 交换寄存器（与移载/交换相关的状态位）",
      "description_en": "get swap register (state bits related to swapping/transfer operations)"
    },
    {
      "action_name": "auto-get_sensor_register",
      "description": "获取 传感器寄存器（原始传感器状态/输入）",
      "description_en": "get sensor register (raw sensor states/inputs)"
    },
    {
      "action_name": "auto-get_incubation_query",
      "description": "获取 指定的孵育查询项（请求某一孵育相关值或状态）",
      "description_en": "get a specified incubation query value or status"
    },
    {
      "action_name": "auto-get_co2",
      "description": "获取 CO2 浓度读数",
      "description_en": "get CO2 concentration"
    },
    {
      "action_name": "auto-get_humidity",
      "description": "获取 湿度读数",
      "description_en": "get humidity"
    },
    {
      "action_name": "auto-get_o2",
      "description": "获取 O2（氧气）浓度读数",
      "description_en": "get O2 concentration"
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取 孵育温度",
      "description_en": "get incubation temperature"
    }
  ],
  "tag_hints": [
    "automated incubator",
    "plate hotel",
    "microplate handling",
    "barcode reader",
    "CO2 control",
    "temperature control",
    "humidity control",
    "shaker control"
  ]
}
